 alpha=page.evaluate('''()=>{let c=document.querySelector('.matrix-ambient'),x=c.getContext('2d'),d=c.width/innerWidth,r=MDCMatrixDebug.regions;let middle=x.getImageData(Math.ceil((r[0].w+2)*d),0,Math.floor((r[1].x-r[0].w-4)*d),c.height).data;let n=0;for(let i=3;i<middle.length;i+=4)if(middle[i])n++;return n}''')
 check('central corridor: zero painted pixels',alpha==0,alpha)
 for i in [0,1]:
  n=page.evaluate('''i=>{const c=document.querySelector('.matrix-ambient'),d=c.width/innerWidth,r=MDCMatrixDebug.regions[i];const p=c.getContext('2d').getImageData(Math.ceil(r.x*d),100,Math.floor((r.w-2)*d),Math.floor(c.height-200)).data;let n=0;for(let k=3;k<p.length;k+=4)if(p[k])n++;return n}''',i)
  check('full-height numerical side '+str(i),n>15000,n)
