 page.locator('[data-effects-open]').click();page.locator('[data-effects-formulas]').check();page.screenshot(path=str(P/'preferences.png'));page.locator('[data-formulas-open]').click();check('120 accessible formula entries',page.locator('[data-formula-record]').count()==120)
